export function studyGuidePromptPack(language: PromptLanguage = 'es'): StudyGuidePromptPack {
  return commonTask[language] ?? commonTask.es;
}

function localize(value: string, p: StudyGuidePromptPack): string {
  const plan = p.plan;
  const replacements: Array<[RegExp, (m: RegExpExecArray) => string]> = [
    [/^(\d+) idea\(s\) extraidas$/, (m) => plan.reasons.ideas(Number(m[1]))],
    [/^(\d+) idea\(s\) principales$/, (m) => plan.reasons.principalIdeas(Number(m[1]))],
    [/^(\d+) pasaje\(s\) indexados$/, (m) => plan.reasons.passages(Number(m[1]))],
    [/^resumen disponible$/, () => plan.reasons.summary], [/^abrible en Zotero$/, () => plan.reasons.zotero], [/^pendiente de lectura$/, () => plan.reasons.unread],
    [/^alta afinidad semantica con el objetivo$/, () => plan.reasons.semantic], [/^estado: (.*)$/, (m) => plan.reasons.status(p.status[(m[1] as keyof typeof p.status)] ?? m[1])],
    [/^obra inicial: (.*)$/, (m) => plan.reasons.initialWork(m[1])], [/^temas: (.*)$/, (m) => plan.reasons.themes(m[1])],
    [/^Situar al autor en (.*)\.$/, (m) => plan.goals.situate(m[1])], [/^Dominar sus (\d+) ideas mas centrales sin perder evidencia\.$/, (m) => plan.goals.ideas(Number(m[1]))],
    [/^Entender con quien dialoga, contradice o extiende dentro del grafo\.$/, () => plan.goals.relations], [/^Leer primero (.*?)(?: \((\d+)\))?\.$/, (m) => plan.goals.firstWork(m[1], m[2] ? Number(m[2]) : null)],
    [/^Usar pasajes indexados para comprobar matices antes de citar\.$/, () => plan.goals.passages], [/^Analizar al menos una obra para convertir este autor en una ficha estudiable\.$/, () => plan.goals.empty],
    [/^Explica la idea "(.*)" sin mirar la ficha\.$/, (m) => plan.questions.explain(m[1])], [/^Relaciona "(.*)" con "(.*)"\.$/, (m) => plan.questions.relate(m[1], m[2])],
    [/^Que postura sostiene sobre (.*)\?$/, (m) => plan.questions.posture(m[1])], [/^Que autores cercanos lo apoyan, extienden o contradicen\?$/, () => plan.questions.relations], [/^Que obra abririas completa en Zotero si tuvieras que citarlo con fuerza\?$/, () => plan.questions.zotero],
    [/^Analiza ideas de sus obras antes de estudiarlo a fondo\.$/, () => plan.actions.analyze], [/^Abre en Zotero la obra prioritaria y lee el texto completo\.$/, () => plan.actions.fullRead], [/^Haz una ronda de repaso con preguntas y conexiones\.$/, () => plan.actions.review], [/^Genera una sesion tutor con pasajes y despues abre Zotero\.$/, () => plan.actions.tutorPassages], [/^Empieza por la obra recomendada y abre Zotero desde la ficha\.$/, () => plan.actions.tutorZotero], [/^Genera una sesion tutor y revisa la evidencia disponible\.$/, () => plan.actions.tutor],
    [/^(\d+) autor\(es\) aparecen sin ideas extraidas; necesitan analisis profundo\.$/, (m) => plan.warnings.noIdeas(Number(m[1]))], [/^(\d+) autor\(es\) tienen ideas pero no pasajes indexados para tutor con texto completo\.$/, (m) => plan.warnings.noPassages(Number(m[1]))], [/^(\d+) autor\(es\) no tienen enlace Zotero disponible en sus obras\.$/, (m) => plan.warnings.noZotero(Number(m[1]))],
    [/^Afinado con (\d+) coincidencia\(s\) semanticas en ideas, pasajes y resumenes\.$/, (m) => p.semanticMatches(Number(m[1]))], [/^Embeddings disponibles, pero sin coincidencias fuertes para el objetivo\.$/, () => p.semanticNone],
    [/^No hay autores pendientes con los filtros actuales\.$/, () => plan.noAuthors], [/^Ruta de (\d+) autor\(es\): empieza por (.*), combina ficha, obras Zotero y preguntas de repaso en sesiones de (\d+) minutos\.$/, (m) => plan.routeSummary(Number(m[1]), m[2], Number(m[3]))],
  ];
  for (const [re, fn] of replacements) { const match = re.exec(value); if (match) return fn(match); }
  return value;
}

/** Translate deterministic fields produced by the unchanged shared planner. */
export function localizeStudyGuidePlan(planValue: StudyGuidePlan, language: PromptLanguage): StudyGuidePlan {
  const p = studyGuidePromptPack(language);
  if (language === 'es') return planValue;
  const plan = { ...planValue };
  if (plan.objective === 'Dominar autores, ideas y obras principales del corpus.') plan.objective = p.defaultObjective;
  plan.summary = localize(plan.summary, p);
  plan.coverageWarnings = plan.coverageWarnings.map((value) => localize(value, p));
  plan.semanticFocusSummary = plan.semanticFocusSummary ? localize(plan.semanticFocusSummary, p) : null;
  plan.phases = plan.phases.map((phase) => ({ ...phase, title: p.plan.phase[phase.id].title, objective: p.plan.phase[phase.id].objective }));
  plan.authors = plan.authors.map((author) => ({
    ...author,
    learningGoals: author.learningGoals.map((value) => localize(value, p)),
    reviewQuestions: author.reviewQuestions.map((value) => localize(value, p)),
    reasons: author.reasons.map((value) => localize(value, p)),
    nextAction: localize(author.nextAction, p),
    recommendedWorks: author.recommendedWorks.map((work) => ({ ...work, reasons: work.reasons.map((value) => localize(value, p)) })),
  }));
  return plan;
}

export function localizedFallbackSteps(p: StudyGuidePromptPack, author: string): StudySessionStep[] {
  return p.session.blocks.map((title, index) => ({ title, body: p.session.stepBodies[index].replace('{author}', author), workIds: [], ideaIds: [], minutes: 0 }));
}
